css:
.scp0:focus { transform: none !important; }
.scp4:active { transform: scale(var(--press-scale)) !important; }
@media (hover: hover) { .scp1:hover { color: var(--text-strong) !important; } .scp2:hover { background: var(--action-ghost-hover) !important; } .scp3:hover { background: color-mix(in srgb, currentcolor 12%, transparent 88%) !important; } .scp5:hover { color: var(--on-ink-strong) !important; } }
.skl-0::before { content: ""; position: absolute; inset: 0px; border: 1.5px solid var(--mk); border-radius: var(--radius-sm); transform: translate(calc(.2em * var(--dir-x)), .2em); opacity: 0.6; z-index: -1; }
.skl-1::after { content: ""; position: absolute; inset: 0px; border: 1.5px solid var(--mk); border-radius: var(--radius-sm); transform: translate(calc(.4em * var(--dir-x)), .4em); opacity: 0.3; z-index: -1; }
.skl-2::after { content: ""; position: absolute; inset-block-end: -0.4em; inset-inline-end: -0.3em; inline-size: 0.7em; block-size: 1.5px; border-radius: 1px; background: var(--mk); transform: rotate(calc(45deg * var(--dir-x))); }
.skl-3::before { content: ""; position: absolute; inset: -1px; z-index: -1; border-radius: inherit; }
